import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import java.util.*;

public final class StarterDeck100TurnHistoryTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){for(int attack:List.of(0,1))plusle(attack,false);plusle(0,true);confusion();for(int pride:List.of(408,419))marnie(pride,true);marnie(408,false);for(boolean use:List.of(false,true))switching(use);System.out.println("StarterDeck100TurnHistoryTest passed: actual attacking identity, both Minun attacks, own-turn expiry, failed confusion, both Pride printings, completed hand-play only and optional switch");}
    static void plusle(int attack,boolean skipped){var m=StarterDeck100PokemonTest.game(139,id(138));StarterDeck100PokemonTest.attack(m,attack);if(m.hasPendingCardSelection())StarterDeck100PokemonTest.select(m,0);m.endTurn(B);if(skipped){m.endTurn(A);m.endTurn(B);}var plus=StarterDeck100PokemonTest.hand(m,id(138));m.playBasicPokemonToBench(A,plus.instanceId());m.switchActiveByEffect(A,A,plus.instanceId());StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==(skipped?20:120),"Minun last own turn history mismatch");m.endTurn(B);m.attack(A,"spark-duo");check(m.lastAttack().finalDamage()==20,"Plusle declaration overwrote prior history or bonus persisted");}
    static void confusion(){boolean found=false;for(int seed=0;seed<100&&!found;seed++){var m=StarterDeck100PokemonTest.gameSeed(139,1,seed,id(138));StarterDeck100PokemonTest.charge(m,0);m.applySpecialConditionByEffect(A,A,SpecialCondition.CONFUSED);int rng=m.randomTranscript().size();m.attack(A,"call-for-family");boolean failed=m.randomTranscript().subList(rng,m.randomTranscript().size()).stream().anyMatch(e->e.operation().equals("attack-confusion:"+A)&&e.result()==1);if(!failed)continue;found=true;m.endTurn(B);var plus=StarterDeck100PokemonTest.hand(m,id(138));m.playBasicPokemonToBench(A,plus.instanceId());m.switchActiveByEffect(A,A,plus.instanceId());StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==20,"failed confusion recorded Minun attack use");}check(found,"no failed-confusion seed");}
    static void marnie(int number,boolean played){var m=StarterDeck100PokemonTest.game(290,id(number));var card=StarterDeck100PokemonTest.hand(m,id(number));TopDeckLookTest.rejects(()->m.playTrainer(A,card.instanceId(),null));if(played){var energy=StarterDeck100PokemonTest.hand(m,"sd100_cn_grass_energy");m.discardHandCardsByEffect(A,A,List.of(energy.instanceId()));m.playTrainer(A,card.instanceId(),null);StarterDeck100PokemonTest.select(m,1);var p=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,p.resolutionId(),p.step(),m.benchPokemonView(A).getFirst().pokemonId());}StarterDeck100PokemonTest.attack(m,1);check(m.lastAttack().finalDamage()==(played?240:120),"Hungry Spikes counted hand presence/failed play or missed Pride printing");if(played){StarterDeck100CombatTest.settleKnockouts(m);m.endTurn(B);m.attack(A,"hangry-spike");check(m.lastAttack().finalDamage()==120,"Pride history survived into next turn");}}
    static void switching(boolean use){var m=StarterDeck100PokemonTest.game(290);var active=m.activePokemonView(A).pokemonId();var bench=m.benchPokemonView(A).getFirst().pokemonId();StarterDeck100PokemonTest.attack(m,0);var c=m.effectChoicePrompt(A);m.chooseEffectOption(A,c.resolutionId(),c.step(),use?0:1);if(use)StarterDeck100PokemonTest.choosePokemon(m,bench);check(m.lastAttack().finalDamage()==30&&m.activePokemonView(A).pokemonId().equals(use?bench:active),"Gnaw and Run optional switch");}
}
